using UnityEngine;
using UnityEditor;
using System.IO;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        if (!EditorApplication.isPlaying) { result.Log("not in play"); return; }
        // Trigger a deferred capture. CaptureScreenshot writes a PNG to disk.
        EditorApplication.delayCall += () => {
            ScreenCapture.CaptureScreenshot("C:/Users/casey/Desktop/Homesteader/tools/.scratch/game_view.png");
            result.Log("CaptureScreenshot queued");
        };
    }
}
